def sum_multiples(n: int) -> int:
    if n <= 0:
        return 0

    def sum_divisible_by(k: int) -> int:
        # Sum of multiples of k up to n: k * (1 + 2 + ... + m) where m = n // k
        m = n // k
        return k * m * (m + 1) // 2

    # Inclusion-exclusion: sum(3) + sum(5) - sum(15)
    return sum_divisible_by(3) + sum_divisible_by(5) - sum_divisible_by(15)
